mapper.select:
select
mu.id,
max(mu.tenant_code) as tenant_code,
max(mu.tenant_name) as tenant_name,
max(mu.user_name) as user_name,
max(mu.nick_name) as nick_name,
max(mu.user_type) as user_type,
max(mu.sex) as sex,
max(mu.avatar) as avatar,
max(mu.phonenumber) as phonenumber,
max(mu.remark) as remark,
max(mu.valid_date) as valid_date,
max(mar.user_status) as status,
group_concat(distinct mr.role_code) as role_code,
group_concat(distinct mr.role_name) as role_name
from micro_user mu
inner join micro_user_role_re re on mu.tenant_code = re.tenant_code and mu.id = re.user_id
inner join micro_role mr on mr.tenant_code = re.tenant_code and mr.id = re.role_id and mr.role_code !='10'
inner join micro_user_app_re mar on mar.tenant_code = mu.tenant_code and mu.id = mar.user_id

    and tenant_code = #{tenantCode}
    and tenant_name like concat('%', #{tenantName}, '%')
    and user_name like concat('%', #{userName}, '%')
    and nick_name like concat('%', #{nickName}, '%')
    and user_type = #{userType}
    and sex = #{sex}
    and avatar = #{avatar}
    and phonenumber = #{phonenumber}
    and valid_date = #{validDate}
    and status = #{status}
    and created_by = #{createdBy}
    and created_date = #{createdDate}
    and last_upd_by = #{lastUpdBy}
    and last_upd_date = #{lastUpdDate}

        and ( mu.user_name like concat('%', #{key}, '%')
        or mu.nick_name like concat('%', #{key}, '%') )


        and mar.app_code = #{appCode}


group by mu.id
order by mu.last_upd_date desc

